// Postgres, shared by the Next.js app and the worker. DATABASE_URL picks the server (default: the postgres of
// docker-compose.tunnel.yml on 127.0.0.1:5433). Tests (VITEST) get an in-memory PGlite per test file instead.
// Migrations are generated by drizzle-kit from src/server/schema.ts into drizzle/ and applied by `dbReady()`.
import { AsyncLocalStorage } from 'node:async_hooks';
import path from 'node:path';

import type { PgDatabase, PgQueryResultHKT } from 'drizzle-orm/pg-core';

import { ROOT } from './config';
import * as schema from './schema';

export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

export const DEV_DATABASE_URL = 'postgres://avs:avs@127.0.0.1:5433/avs';
const MIGRATIONS = path.join(ROOT, 'drizzle');
/** Any fixed number: the advisory lock that keeps web and worker from migrating at the same time. */
const MIGRATION_LOCK = 482_613;

interface Handle {
  db: Db;
  ready: Promise<void>;
  close: () => Promise<void>;
}

async function openPostgres(): Promise<Handle> {
  const { default: postgres } = await import('postgres');
  const { drizzle } = await import('drizzle-orm/postgres-js');
  const { migrate } = await import('drizzle-orm/postgres-js/migrator');
  const url = process.env.DATABASE_URL || DEV_DATABASE_URL;
  const client = postgres(url, {
    max: Number(process.env.AVS_DB_POOL) || 10,
    onnotice: () => {},
    // Days in the cost charts follow the server's clock, as they did on SQLite ('localtime').
    connection: { TimeZone: Intl.DateTimeFormat().resolvedOptions().timeZone },
  });
  const db = drizzle(client, { schema }) as unknown as Db;
  // Migrations on a connection of their own, holding a session advisory lock so web and worker take turns.
  const ready = (async () => {
    const one = postgres(url, { max: 1, onnotice: () => {} });
    try {
      await one`SELECT pg_advisory_lock(${MIGRATION_LOCK})`;
      await migrate(drizzle(one, { schema }), { migrationsFolder: MIGRATIONS });
    } finally {
      await one.end();
    }
  })();
  return { db, ready, close: () => client.end() };
}

async function openPglite(): Promise<Handle> {
  const { PGlite } = await import('@electric-sql/pglite');
  const { drizzle } = await import('drizzle-orm/pglite');
  const { migrate } = await import('drizzle-orm/pglite/migrator');
  const client = new PGlite();
  const db = drizzle(client, { schema }) as unknown as Db;
  return { db, ready: migrate(drizzle(client, { schema }), { migrationsFolder: MIGRATIONS }), close: () => client.close() };
}

// One pool per process; survives Next.js dev hot reloads.
const g = globalThis as unknown as { __avsDb?: Promise<Handle>; __avsTx?: AsyncLocalStorage<Db> };
const handle = () => (g.__avsDb ??= process.env.VITEST && !process.env.DATABASE_URL ? openPglite() : openPostgres());
let opened: Handle | undefined;

/** Opens the database and applies pending migrations. The API guard, the worker and tests await it first. */
export async function dbReady(): Promise<void> {
  const h = await handle();
  await h.ready;
  opened = h;
}

const txStore = (g.__avsTx ??= new AsyncLocalStorage<Db>());

/** The database, or the open transaction when called inside `transaction()`. Only after `dbReady()`. */
export function orm(): Db {
  const tx = txStore.getStore();
  if (tx) return tx;
  if (!opened) throw new Error('Database not ready: await dbReady() first');
  return opened.db;
}

/**
 * Runs `fn` in one transaction. Repositories called inside it use the transaction through `orm()` (the same
 * AsyncLocalStorage idea as ctx()), so nothing passes a connection around. Nested calls join the outer one.
 */
export async function transaction<T>(fn: () => Promise<T>): Promise<T> {
  if (txStore.getStore()) return fn();
  return orm().transaction((tx) => txStore.run(tx as unknown as Db, fn));
}

/** Closes the pool (scripts and tests). */
export async function closeDb(): Promise<void> {
  if (g.__avsDb) await (await g.__avsDb).close();
  g.__avsDb = undefined;
  opened = undefined;
}

/** The rows of `orm().execute(sql\`…\`)`: postgres.js answers an array, PGlite an object with `rows`. */
export const rowsOf = <T>(result: unknown): T[] => (Array.isArray(result) ? result : (result as { rows: T[] }).rows) as T[];

export const now = () => new Date().toISOString();
export const json = <T>(text: unknown, fallback: T): T => {
  if (typeof text !== 'string') return fallback;
  try {
    return JSON.parse(text) as T;
  } catch {
    return fallback;
  }
};
